package main

import "fmt"

func main() {
	src := []int{1, 2, 3}

	// 1) 按源切片长度分配一块新的底层数组
	dst := make([]int, len(src))

	// 2) 目标在前，源在后；返回值是复制的元素个数
	n := copy(dst, src)
	fmt.Println("复制的元素个数:", n) // 3

	// 3) 改副本，原切片不动
	dst[0] = 100
	fmt.Println("src:", src) // [1 2 3]
	fmt.Println("dst:", dst) // [100 2 3]

	// 4) 反过来改原切片，副本也不动
	src[1] = 200
	fmt.Println("src:", src) // [1 200 3]
	fmt.Println("dst:", dst) // [100 2 3]

	// 5) 打印底层数组地址，两行不同
	fmt.Printf("src 底层数组地址: %p\n", src)
	fmt.Printf("dst 底层数组地址: %p\n", dst)
}

