content.answer:
func clone(src []int) []int {
	dst := make([]int, len(src))
	copy(dst, src)
	return dst
}

func TestCloneNoSharing(t *testing.T) {
	s := []int{1, 2, 3}
	c := clone(s)

	c[0] = 99
	if s[0] != 1 {
		t.Fatalf("改副本影响了原切片: s=%v", s)
	}

	s[1] = 88
	if c[1] != 2 {
		t.Fatalf("改原切片影响了副本: c=%v", c)
	}
}
两个方向的断言都要有，才说明真的互不影响。

